#!/usr/bin/env python3
import sys, os, math, time
from decimal import Decimal, getcontext

getcontext().prec = 120

MAX_FLOAT_MESSAGE = "Error: to large to process! Max value: "

class EvaError(Exception):
    def __init__(self, message):
        super().__init__(message)
        self.message = message

class DomainError(EvaError):
    def __init__(self): super().__init__("Domain Error: Out of bounds!")
class DivideZeroError(EvaError):
    def __init__(self): super().__init__("Math Error: Divide by zero error!")
class OverflowEvaError(EvaError):
    def __init__(self): super().__init__(MAX_FLOAT_MESSAGE)
class ParserError(EvaError):
    def __init__(self): super().__init__("Parser Error: Too many operators, too few operands")
class MismatchedError(EvaError):
    def __init__(self): super().__init__("Syntax Error: Mismatched parentheses!")
class NoPrevError(EvaError):
    def __init__(self): super().__init__("Syntax Error: No previous answer!")
class TooFewArgs(EvaError):
    def __init__(self, n): super().__init__(f"Parser Error: To few arguments for function, need {n}")

FUNCTION_ARITY = {
    'sin':1, 'cos':1, 'tan':1, 'csc':1, 'sec':1, 'cot':1,
    'sinh':1, 'cosh':1, 'tanh':1,
    'asin':1, 'acos':1, 'atan':1, 'acsc':1, 'asec':1, 'acot':1,
    'ln':1, 'log2':1, 'log10':1, 'sqrt':1, 'ceil':1, 'floor':1, 'abs':1,
    'exp':1, 'round':1, 'rad':1, 'deg':1,
    'log':2, 'nroot':2,
}
FUNC_NAMES = sorted(FUNCTION_ARITY, key=len, reverse=True)
DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

class Token:
    __slots__ = ('typ','val')
    def __init__(self, typ, val=None):
        self.typ = typ; self.val = val
    def __repr__(self):
        return f"Token({self.typ!r},{self.val!r})"

def is_boundary(ch):
    return ch == '' or ch.isdigit() or ch in '+-*/^%!(),._'

def tokenize(expr, prev_value=None, allow_prev_zero=True):
    s = ''.join(expr.split())
    if s == '':
        return []
    if s.count('.') > 1 and all(c.isdigit() or c=='.' for c in s):
        raise ParserError()
    tokens=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c.isdigit() or c=='.':
            start=i; dot=0
            while i<n and (s[i].isdigit() or s[i]=='.'):
                if s[i]=='.': dot += 1
                i += 1
            if dot>1:
                raise ParserError()
            txt=s[start:i]
            if txt == '.':
                raise EvaError("Syntax Error: Unexpected token: '.'")
            try:
                val=float(txt)
            except Exception:
                raise ParserError()
            tokens.append(Token('num', val))
            continue
        if c == '_':
            if prev_value is None:
                if allow_prev_zero:
                    val=0.0
                else:
                    raise NoPrevError()
            else:
                val=prev_value
            tokens.append(Token('num', float(val)))
            i+=1; continue
        if c.isalpha():
            # Known constants split when followed by a numeric boundary; do not split words like "pie".
            if s.startswith('pi', i) and (i+2==n or not s[i+2].isalpha()):
                if i+2<n and s[i+2]=='(':
                    raise EvaError("Syntax Error: Unknown function 'pi'")
                tokens.append(Token('num', math.pi)); i+=2; continue
            if s.startswith('e', i) and (i+1==n or not s[i+1].isalpha()):
                if i+1<n and s[i+1]=='(':
                    raise EvaError("Syntax Error: Unknown function 'e'")
                tokens.append(Token('num', math.e)); i+=1; continue
            # If the alphabetic run is followed by '(', it is a function name (known or not).
            j=i
            while j<n and s[j].isalpha(): j+=1
            word=s[i:j]
            if j<n and s[j]=='(':
                if word in FUNCTION_ARITY:
                    tokens.append(Token('func', word)); i=j; continue
                raise EvaError(f"Syntax Error: Unknown function '{word}'")
            # Known function used without parentheses.
            for name in FUNC_NAMES:
                if s.startswith(name, i):
                    raise EvaError(f"Syntax Error: Function '{name}' expected parentheses")
            # Constants followed immediately by digits, e.g. pi2, e3.
            if s.startswith('pi', i) and i+2<n and s[i+2].isdigit():
                tokens.append(Token('num', math.pi)); i+=2; continue
            if s.startswith('e', i) and i+1<n and s[i+1].isdigit():
                tokens.append(Token('num', math.e)); i+=1; continue
            if j<n and s[j].isdigit():
                raise EvaError(f"Syntax Error: Unexpected character '{s[i:min(n,i+2)]}'")
            # Unknown bare identifiers degrade to the parser's generic operand error.
            raise ParserError()
        if c in '+-*/^%,()!':
            if c == '*':
                if i+1<n and s[i+1]=='*':
                    tokens.append(Token('op','^')); i+=2; continue
                tokens.append(Token('op','*')); i+=1; continue
            if c in '+-/^%':
                tokens.append(Token('op', c)); i+=1; continue
            if c == '(':
                tokens.append(Token('lp')); i+=1; continue
            if c == ')':
                tokens.append(Token('rp')); i+=1; continue
            if c == ',':
                tokens.append(Token('comma')); i+=1; continue
            if c == '!':
                tokens.append(Token('fact')); i+=1; continue
        # Match the original style for alnum fragments such as x1/E3, otherwise token.
        if c.isalpha() and i+1<n:
            raise EvaError(f"Syntax Error: Unexpected character '{s[i:min(n,i+2)]}'")
        raise EvaError(f"Syntax Error: Unexpected token: '{c}'")
    return insert_implicit_mul(tokens)

def insert_implicit_mul(tokens):
    out=[]
    for t in tokens:
        if out and need_mul(out[-1], t):
            out.append(Token('op','*'))
        out.append(t)
    return out

def need_mul(a,b):
    # Multiplication inserted for common calculator shorthand.  Deliberately not
    # after postfix factorial or after ')' except before another parenthesized value.
    if a.typ == 'num' and (b.typ in ('num','func','lp')):
        return True
    if a.typ == 'rp' and b.typ == 'lp':
        return True
    return False

def balance_parentheses(tokens):
    depth=0
    for t in tokens:
        if t.typ == 'lp': depth += 1
        elif t.typ == 'rp':
            depth -= 1
            if depth < 0: raise MismatchedError()
    return tokens + [Token('rp') for _ in range(depth)]

class Parser:
    def __init__(self, tokens, angle_unit='degree'):
        self.tokens=tokens; self.i=0; self.angle_unit=angle_unit
    def peek(self):
        if self.i < len(self.tokens): return self.tokens[self.i]
        return None
    def pop(self):
        t=self.peek(); self.i += 1; return t
    def parse(self):
        if not self.tokens:
            return 0.0
        val=self.parse_expr()
        if self.peek() is not None:
            if self.peek().typ == 'comma':
                raise MismatchedError()
            raise ParserError()
        return checked(val)
    def parse_expr(self):
        v=self.parse_term()
        while True:
            t=self.peek()
            if t and t.typ=='op' and t.val in ('+','-'):
                op=t.val; self.pop(); r=self.parse_term()
                v = v + r if op=='+' else v - r
                v = checked(v)
            else: break
        return v
    def parse_term(self):
        v=self.parse_power()
        while True:
            t=self.peek()
            if t and t.typ=='op' and t.val in ('*','/','%'):
                op=t.val; self.pop(); r=self.parse_power()
                if op=='*': v = v*r
                elif op=='/':
                    if r == 0: raise DivideZeroError()
                    v = v/r
                else:
                    if r == 0: raise OverflowEvaError()
                    v = math.fmod(v, r)
                v=checked(v)
            else: break
        return v
    def parse_power(self):
        v=self.parse_signed_postfix()
        t=self.peek()
        if t and t.typ=='op' and t.val=='^':
            self.pop(); r=self.parse_power()
            try:
                v = math.pow(v, r)
            except ValueError:
                raise OverflowEvaError()
            except OverflowError:
                raise OverflowEvaError()
            v=checked(v)
        return v
    def parse_signed_postfix(self):
        sign=1
        while True:
            t=self.peek()
            if t and t.typ=='op' and t.val in ('+','-'):
                if t.val=='-': sign *= -1
                self.pop()
            else: break
        v=self.parse_primary()*sign
        while True:
            t=self.peek()
            if t and t.typ=='fact':
                self.pop(); v=factorial(v)
            else: break
        return checked(v)
    def parse_primary(self):
        t=self.peek()
        if t is None: raise ParserError()
        if t.typ=='num':
            self.pop(); return t.val
        if t.typ=='lp':
            self.pop(); v=self.parse_expr()
            if self.peek() and self.peek().typ=='rp':
                self.pop(); return v
            raise MismatchedError()
        if t.typ=='func':
            return self.parse_function()
        if t.typ=='rp' or t.typ=='comma':
            raise ParserError()
        if t.typ=='op':
            raise ParserError()
        raise ParserError()
    def parse_function(self):
        name=self.pop().val
        if not (self.peek() and self.peek().typ=='lp'):
            raise EvaError(f"Syntax Error: Function '{name}' expected parentheses")
        self.pop()  # lp
        args=[]
        if self.peek() and self.peek().typ=='rp':
            self.pop()
        else:
            while True:
                if self.peek() is None:
                    raise MismatchedError()
                if self.peek().typ in ('comma','rp'):
                    # missing argument
                    need=FUNCTION_ARITY[name]
                    raise TooFewArgs(need)
                args.append(self.parse_expr())
                if self.peek() and self.peek().typ=='comma':
                    self.pop()
                    if self.peek() and self.peek().typ=='rp':
                        raise TooFewArgs(FUNCTION_ARITY[name])
                    continue
                break
            if self.peek() and self.peek().typ=='rp':
                self.pop()
            else:
                raise MismatchedError()
        ar=FUNCTION_ARITY[name]
        if len(args) < ar:
            raise TooFewArgs(ar)
        if len(args) > ar:
            raise ParserError()
        return call_func(name, args, self.angle_unit)

def checked(v):
    try:
        if not math.isfinite(float(v)):
            raise OverflowEvaError()
    except OverflowEvaError:
        raise
    except Exception:
        raise OverflowEvaError()
    return float(v)

def factorial(v):
    if v < 0 or abs(v-round(v)) > 1e-12:
        raise DomainError()
    n=int(round(v))
    try:
        return checked(float(math.factorial(n)))
    except OverflowError:
        raise OverflowEvaError()

def to_radians(x, unit):
    if unit == 'radian':
        return x
    # The observed gradian mode behaves like degree mode.
    return math.radians(x)

def call_func(name, args, angle_unit):
    x=args[0]
    try:
        if name == 'sin': return checked(math.sin(to_radians(x, angle_unit)))
        if name == 'cos': return checked(math.cos(to_radians(x, angle_unit)))
        if name == 'tan': return checked(math.tan(to_radians(x, angle_unit)))
        if name == 'csc':
            y=math.sin(to_radians(x, angle_unit))
            if y == 0: raise DomainError()
            return checked(1.0/y)
        if name == 'sec':
            y=math.cos(to_radians(x, angle_unit))
            if y == 0: raise DomainError()
            return checked(1.0/y)
        if name == 'cot':
            y=math.tan(to_radians(x, angle_unit))
            if y == 0: raise DomainError()
            return checked(1.0/y)
        if name == 'sinh': return checked(math.sinh(x))
        if name == 'cosh': return checked(math.cosh(x))
        if name == 'tanh': return checked(math.tanh(x))
        if name == 'asin':
            if x < -1 or x > 1: raise DomainError()
            return checked(math.asin(x))
        if name == 'acos':
            if x < -1 or x > 1: raise DomainError()
            return checked(math.acos(x))
        if name == 'atan': return checked(math.atan(x))
        if name == 'acsc':
            if x == 0 or abs(1.0/x) > 1: raise DomainError()
            return checked(math.asin(1.0/x))
        if name == 'asec':
            if x == 0 or abs(1.0/x) > 1: raise DomainError()
            return checked(math.acos(1.0/x))
        if name == 'acot':
            if x == 0: return checked(math.pi/2)
            return checked(math.atan(1.0/x))
        if name == 'ln':
            if x <= 0: raise DomainError()
            return checked(math.log(x))
        if name == 'log2':
            if x <= 0: raise DomainError()
            return checked(math.log2(x))
        if name == 'log10':
            if x <= 0: raise DomainError()
            return checked(math.log10(x))
        if name == 'sqrt':
            if x < 0: raise DomainError()
            return checked(math.sqrt(x))
        if name == 'ceil': return checked(math.ceil(x))
        if name == 'floor': return checked(math.floor(x))
        if name == 'abs': return checked(abs(x))
        if name == 'exp': return checked(math.exp(x))
        if name == 'round':
            return checked(math.floor(x+0.5) if x >= 0 else math.ceil(x-0.5))
        if name == 'rad': return checked(math.radians(x))
        if name == 'deg': return checked(math.degrees(x))
        if name == 'log':
            a,b=args
            if a <= 0 or b == 1: raise DomainError()
            if b < 0: raise DomainError()
            if b == 0:
                # f64 ln(0) is -inf; finite numerator divided by it is signed zero.
                return checked(-0.0 if a > 1 else 0.0)
            return checked(math.log(a)/math.log(b))
        if name == 'nroot':
            a,b=args
            if a < 0: raise DomainError()
            return checked(math.pow(a, 1.0/b))
    except DomainError:
        raise
    except OverflowEvaError:
        raise
    except ValueError:
        raise DomainError()
    except OverflowError:
        raise OverflowEvaError()
    raise EvaError(f"Syntax Error: Unknown function '{name}'")

def eval_expr(expr, angle_unit='degree', prev_value=0.0, allow_prev_zero=True):
    toks = tokenize(expr, prev_value, allow_prev_zero)
    toks = balance_parentheses(toks)
    return Parser(toks, angle_unit).parse()

def add_commas_int(intpart):
    sign=''
    s=intpart
    if s.startswith('-'):
        sign='-'; s=s[1:]
    # s may already contain spaces in non-decimal mode; in that case group verbatim.
    if ' ' in s:
        raw=sign+s if sign else s
        parts=[]
        while raw:
            parts.append(raw[-3:]); raw=raw[:-3]
        return ','.join(reversed(parts))
    parts=[]
    while len(s)>3:
        parts.append(s[-3:]); s=s[:-3]
    parts.append(s)
    return sign + ','.join(reversed(parts))

def format_base10(v, fix):
    v=checked(v)
    s = f"{v:.{fix}f}"
    if '.' in s:
        a,b=s.split('.',1)
        return add_commas_int(a)+'.'+b
    return add_commas_int(s)

def int_to_base(n, base):
    if n == 0: return '0'
    out=''
    while n>0:
        out = DIGITS[n % base] + out
        n //= base
    return out

def group_padded(s):
    raw = f"{s:>10}"
    parts=[]
    while raw:
        parts.append(raw[-3:]); raw=raw[:-3]
    return ','.join(reversed(parts))

def format_nondecimal(v, fix, base):
    if base == 1:
        while True:
            time.sleep(3600)
    v=checked(v)
    neg = math.copysign(1.0, v) < 0
    # Observed conversion first rounds the value to the selected decimal precision.
    dec = f"{abs(v):.{fix}f}"
    if 'e' in dec or 'E' in dec:
        dec = format(abs(v), f'.{fix}f')
    int_s, frac_s = (dec.split('.',1)+[''])[:2] if '.' in dec else (dec,'')
    int_digits = int_to_base(int(int_s or '0'), base)
    if neg:
        int_digits = '-' + int_digits
    frac = Decimal('0.' + (frac_s or '0'))
    out_frac=''
    for _ in range(fix):
        frac *= base
        d = int(frac)
        if d < 0: d = 0
        if d >= base: d = base-1
        out_frac += DIGITS[d]
        frac -= d
        if frac == 0:
            break
    if out_frac == '':
        out_frac = '0'
    return group_padded(int_digits) + '.' + out_frac

def format_value(v, fix=10, base=10):
    if base == 10:
        return format_base10(v, fix)
    return format_nondecimal(v, fix, base)

HELP = """Calculator REPL similar to bc(1)

Usage: {prog} [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Optional expression string to run eva in command mode

Options:
  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]
  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]
  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]
  -h, --help                     Print help
  -V, --version                  Print version
"""

def usage(prog):
    return f"Usage: {prog} [OPTIONS] [INPUT]"

def cli_error(msg, prog, tip_arg=None, angle_values=False):
    sys.stderr.write("error: " + msg + "\n")
    if angle_values:
        sys.stderr.write("  [possible values: degree, radian, gradian]\n")
    if tip_arg is not None:
        sys.stderr.write(f"\n  tip: to pass '{tip_arg}' as a value, use '-- {tip_arg}'\n")
    if not msg.startswith('a value is required') and not msg.startswith('invalid value'):
        sys.stderr.write("\n" + usage(prog) + "\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    return 2

def parse_int_value(val, optname, display, lo, hi, prog):
    try:
        if val.startswith('+'):
            # Rust's usize parser accepts +?  Keep simple.
            x=int(val,10)
        else:
            x=int(val,10)
    except Exception:
        cli_error(f"invalid value '{val}' for '{optname} <{display}>': invalid digit found in string", prog)
        raise SystemExit(2)
    if x < lo or x > hi:
        cli_error(f"invalid value '{val}' for '{optname} <{display}>': {x} is not in {lo}..={hi}", prog)
        raise SystemExit(2)
    return x

def parse_args(argv):
    prog=os.path.basename(argv[0]) or 'executable'
    fix=10; base=10; angle='degree'; inp=None
    i=1; after=False
    while i < len(argv):
        a=argv[i]
        if not after and a == '--':
            after=True; i+=1; continue
        if not after and a in ('-h','--help'):
            sys.stdout.write(HELP.format(prog=prog)); raise SystemExit(0)
        if not after and a in ('-V','--version'):
            sys.stdout.write('eva 0.3.1\n'); raise SystemExit(0)
        if not after and (a == '-f' or a == '--fix'):
            if i+1 >= len(argv): raise SystemExit(cli_error("a value is required for '--fix <FIX>' but none was supplied", prog))
            val=argv[i+1]
            if val.startswith('-'):
                raise SystemExit(cli_error(f"unexpected argument '{val}' found", prog, val))
            fix=parse_int_value(val, '--fix', 'FIX', 1,64, prog); i+=2; continue
        if not after and a.startswith('--fix='):
            val=a.split('=',1)[1]
            fix=parse_int_value(val, '--fix', 'FIX', 1,64, prog); i+=1; continue
        if not after and (a == '-b' or a == '--base'):
            if i+1 >= len(argv): raise SystemExit(cli_error("a value is required for '--base <RADIX>' but none was supplied", prog))
            val=argv[i+1]
            if val.startswith('-'):
                raise SystemExit(cli_error(f"unexpected argument '{val}' found", prog, val))
            base=parse_int_value(val, '--base', 'RADIX', 1,36, prog); i+=2; continue
        if not after and a.startswith('--base='):
            val=a.split('=',1)[1]
            base=parse_int_value(val, '--base', 'RADIX', 1,36, prog); i+=1; continue
        if not after and (a == '-a' or a == '--angle_unit'):
            if i+1 >= len(argv): raise SystemExit(cli_error("a value is required for '--angle_unit <angle_unit>' but none was supplied", prog, angle_values=True))
            val=argv[i+1]
            if val.startswith('-'):
                raise SystemExit(cli_error(f"unexpected argument '{val}' found", prog, val))
            if val not in ('degree','radian','gradian'):
                raise SystemExit(cli_error(f"invalid value '{val}' for '--angle_unit <angle_unit>'", prog, angle_values=True))
            angle=val; i+=2; continue
        if not after and a.startswith('--angle_unit='):
            val=a.split('=',1)[1]
            if val not in ('degree','radian','gradian'):
                raise SystemExit(cli_error(f"invalid value '{val}' for '--angle_unit <angle_unit>'", prog, angle_values=True))
            angle=val; i+=1; continue
        if not after and a.startswith('-'):
            raise SystemExit(cli_error(f"unexpected argument '{a}' found", prog, a))
        if inp is None:
            inp=a; i+=1; continue
        # Extra positional argument.
        tip = None if after else (a if a.startswith('-') else None)
        raise SystemExit(cli_error(f"unexpected argument '{a}' found", prog, tip))
    return prog, fix, base, angle, inp

def cache_paths():
    home=os.environ.get('HOME') or os.path.expanduser('~')
    return (os.path.join(home,'.local','share','eva','history.txt'),
            os.path.join(home,'.cache','eva','previous_ans.txt'))

def write_prev(val):
    _hist, prevp = cache_paths()
    try:
        os.makedirs(os.path.dirname(prevp), exist_ok=True)
        if abs(val-round(val)) < 1e-12:
            txt=str(int(round(val)))
        else:
            txt=(f"{val:.10f}".rstrip('0').rstrip('.'))
        with open(prevp,'w') as f: f.write(txt)
    except Exception:
        pass

def append_history(lines):
    hist,_prev = cache_paths()
    try:
        os.makedirs(os.path.dirname(hist), exist_ok=True)
        new = not os.path.exists(hist)
        with open(hist,'a') as f:
            if new: f.write('#V2\n')
            for line in lines:
                if line != '': f.write(line+'\n')
    except Exception:
        pass

def command_mode(inp, fix, base, angle):
    if inp == '':
        print('No previous history.')
        write_prev(0.0)
        return 0
    try:
        val=eval_expr(inp, angle, prev_value=0.0, allow_prev_zero=True)
        print(format_value(val, fix, base))
        return 0
    except EvaError as e:
        sys.stderr.write(e.message+'\n')
        return 1

def repl_mode(fix, base, angle):
    hist, prevp = cache_paths()
    if not os.path.exists(hist):
        print('No previous history.')
    prev=None
    last=0.0
    lines=[]
    interactive=sys.stdin.isatty()
    while True:
        try:
            if interactive:
                sys.stdout.write('> '); sys.stdout.flush()
            line=sys.stdin.readline()
            if line == '': break
            line=line.rstrip('\n')
        except (EOFError, KeyboardInterrupt):
            break
        try:
            val=eval_expr(line, angle, prev_value=prev, allow_prev_zero=False)
            print(format_value(val, fix, base))
            prev=val; last=val
        except EvaError as e:
            print(e.message)
        lines.append(line)
    write_prev(last)
    append_history(lines)
    return 0

def main(argv):
    try:
        prog, fix, base, angle, inp = parse_args(argv)
    except SystemExit as e:
        return int(e.code or 0)
    if inp is not None:
        return command_mode(inp, fix, base, angle)
    return repl_mode(fix, base, angle)

if __name__ == '__main__':
    sys.exit(main(sys.argv))
